let pointer;canvas.onpointerdown=e=>{pointer={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(!pointer)return;state.pan[0]+=e.clientX-pointer.x;state.pan[1]+=e.clientY-pointer.y;pointer.x=e.clientX;pointer.y=e.clientY;draw();};canvas.onpointerup=e=>{if(pointer&&Math.hypot(e.clientX-pointer.startX,e.clientY-pointer.startY)<5&&state.view==='top'){const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left-origin[0])/scale,z=-(e.clientY-r.top-origin[1])/scale;let hit;for(const p of layouts[state.layout].placements){const [a,b,c,d,tx,tz]=p.spriteTransform,det=a*d-b*c,lx=(d*(x-tx)-c*(z-tz))/det,lz=(-b*(x-tx)+a*(z-tz))/det,s=assets.sprites.find(s=>s.id===p.sprite);if(Math.abs(lx)<(s.lengthCells||1)/2+.2&&Math.abs(lz)<.4)hit=p;}if(hit){state.selected=hit.id;$('#selection').textContent=hit.id+' · '+(hit.deviceId==='rail'?'栏杆':'立柱')+' · 共用 '+hit.sprite;draw();}}pointer=null;};canvas.onpointercancel=()=>pointer=null;canvas.addEventListener('wheel',e=>{e.preventDefault();state.zoom=Math.max(.5,Math.min(5,state.zoom*(e.deltaY<0?1.1:1/1.1)));draw();},{passive:false});new ResizeObserver(draw).observe(stage);
(async()=>{try{manifest=await json('manifest.json');assets=await json(manifest.profiles.find(p=>p.pixelsPerCell===64)?.assets||manifest.profiles[0].assets);await Promise.all(manifest.layouts.map(async l=>{layouts[l.id]=await json(l.file);images[l.id]=await image(l.preview);}));await Promise.all(assets.sprites.map(async s=>images[s.id]=await image(s.file)));images.grass=await image(manifest.background.file);$('#components').innerHTML=assets.sprites.map(s=>'<article class="component"><b>'+(s.type==='post'?'立柱':s.lengthCells+'格栏杆')+'</b><img src="previews/'+s.id+'-detail.webp" alt="'+s.id+'"><a href="'+s.file+'">俯视贴图</a><a href="'+s.heightFile+'">高度图</a></article>').join('');for(const p of manifest.downloads||[]){const a=$('[data-pack="'+p.key+'"]');if(a){a.href=p.url;a.hidden=false;}}$('#loading').hidden=true;draw();window.fenceViewer={state,manifest,assets,layouts,draw};}catch(e){$('#loading').textContent='加载失败：'+e.message;console.error(e);}})();
